#include <vector>
#include <omp.h>

double productWithInverses(std::vector<double> const& x) {
    double prod = 1.0;

    #pragma omp parallel for reduction(*:prod)
    for (int i = 0; i < static_cast<int>(x.size()); ++i) {
        if ((i & 1) == 0) {
            prod *= x[i];
        } else {
            prod *= 1.0 / x[i];
        }
    }

    return prod;
}
